import json

rows=[json.loads(l) for l in open('outputs/metrics.jsonl')]

# Check all keys in step 139 (before final) and 150
for s in [139, 140, 141, 149, 150]:
    for r in rows:
        if r['step']==s:
            d=r['data']
            keys=sorted(k for k in d if 'loss' in k or 'pg_loss' in k or 'reward' in k or 'entropy' in k or 'kl' in k or 'clip' in k)
            print(f'step {s}:', json.dumps({k:(round(d[k],4) if isinstance(d[k],float) else d[k]) for k in keys}))

# Also check for any 'reward' key that's not critic
for s in [130, 135, 140, 145, 150]:
    for r in rows:
        if r['step']==s:
            d=r['data']
            reward_keys=[k for k in d if 'reward' in k]
            print(f'step {s} reward keys:', sorted(reward_keys))
            break
PYEOF

